import SwiftUI
import AppKit
import AppState
struct SupportCommands: View {@Environment(\.openWindow) var open;var body:some View{Button(L("About Bottle Archive")){open(id:"about")}}}
struct HelpCommand: View {@Environment(\.openWindow) var open;var body:some View{Button(L("Bottle Archive Help")){open(id:"help")}.keyboardShortcut("?",modifiers:.command)}}
struct AboutView: View {
 var body:some View {VStack(spacing:14){Image(nsImage:NSApp.applicationIconImage).resizable().frame(width:76,height:76);Text("Bottle Archive").font(.title2.weight(.semibold));Text(L("Create verified CrossOver bottle backups.")).foregroundStyle(.secondary);Text("1.1.1 (3)").font(.caption);Text(L("Made by Adrian Feeger")).font(.callout);Link("adrianfeeger.com",destination:URL(string:"https://adrianfeeger.com")!);Text(L("Your files stay on your Mac and chosen drives.")).font(.caption).foregroundStyle(.secondary)}.padding(24)}
}
struct HelpView: View {
 var body:some View {ScrollView{VStack(alignment:.leading,spacing:18){Text(L("Bottle Archive Help")).font(.title2.weight(.semibold));section("Create a backup","Close the bottle's Windows applications. Choose a bottle and destination, select compression, then choose Create Archive. The app verifies the backup before completing it.");section("Compression and estimates","Fast uses less compression time. Maximum spends more time trying to reduce size. Size estimates use a small sample and may differ from the final archive.");section("Thread count","Automatic leaves two cores available when possible. Choose a larger thread count to use more CPU for compression. Export and verification can still limit the speed.");section("Restore a backup","In CrossOver, choose Bottle > Import Bottle Archive and select the completed .cxarchive file.");section("External files","Linked Mac folders are not included. Back up saves and documents stored outside the bottle separately.");section("Cancel and recover","Cancel stops this archive job. Existing backups are preserved. If a drive disconnects, an incomplete .partial file may remain; reconnect the drive and remove that incomplete file.");section("Privacy","Archive contents are processed locally. The app keeps your chosen folders and a small local result record. It does not upload your files.");Text(L("Refresh Bottles: Command-R. Create Archive: Return. Cancel: Escape.")).font(.caption).foregroundStyle(.secondary)}.padding(24)}}
 private func section(_ title:String,_ content:String)->some View {VStack(alignment:.leading,spacing:5){Text(L(title)).font(.headline);Text(L(content)).foregroundStyle(.secondary).fixedSize(horizontal:false,vertical:true)}}
}
@MainActor func showDiagnostics(_ model:ArchiveViewModel){let a=NSAlert();a.messageText=L("Diagnostics");a.informativeText=model.diagnostics();a.addButton(withTitle:L("Copy"));a.addButton(withTitle:L("Cancel"));if a.runModal() == .alertFirstButtonReturn{NSPasteboard.general.clearContents();NSPasteboard.general.setString(model.diagnostics(),forType:.string)}}
